    val = r.get('result')
    if isinstance(val, str):
        try:
            val = json.loads(val)
        except:
            pass
    facts['read_results'].append({
        'index': i,
        'api': r.get('api'),
        'value': val
    })

print(json.dumps({'queries': [], 'facts': facts}))

